import AccessibilitySettingsModal from"theme_president/accessibilitysettings_modal";import $ from"jquery";export const init=async()=>{$("#accessibilitysettings-control").click(function(t){t.preventDefault(),openModal()})};const openModal=async()=>{(await AccessibilitySettingsModal.create({})).show()};